def merge(intervals):
    """Merge overlapping or touching [start, end] intervals.

    Returns a new list of disjoint intervals sorted by start, without
    modifying the input.
    """
    if not intervals:
        return []

    ordered = sorted((list(pair) for pair in intervals), key=lambda p: (p[0], p[1]))
    merged = [list(ordered[0])]

    for start, end in ordered[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged
